function rankArticleSearch(records,query,normalize){
 if(!query)return [];
 return records.map((article,order)=>({article,order,title:normalize(article.title),text:normalize(article.title+' '+article.topic+' '+article.detail)}))
  .filter(row=>row.text.includes(query))
  .map(row=>({...row,priority:row.title===query?3:row.title.startsWith(query)?2:row.title.includes(query)?1:0}))
  .sort((a,b)=>b.priority-a.priority||a.order-b.order)
  .map(row=>row.article);
}
