initAsideDock();

initReadingFooterAccordion();
initArticleShare();

/* Gallery entrance: logo 800ms, rail 456+440ms, top-axis folds 420/90ms. */
async function initBlogEntrance() {
  const root = document.documentElement;
  const reduced = matchMedia('(prefers-reduced-motion: reduce)');
  const animations = [];
  const finish = () => { animations.forEach(a => a.cancel()); root.classList.remove('blog-enter-pending'); };
  if (reduced.matches || new URLSearchParams(location.search).has('editor_view')) { finish(); return; }
  try {
    await document.fonts.ready;
    await new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve)));
    const ease = 'cubic-bezier(.16,1,.3,1)';
    const animate = (element, frames, duration, delay=0, easing=ease) => {
      const a = element.animate(frames, {duration, delay, easing, fill:'both'});
      animations.push(a); return a;
    };
    const rail = document.querySelector('.search-rail');
    animate(rail, [{clipPath:`inset(0 ${Math.max(0,rail.offsetWidth-rail.offsetHeight)}px 0 0 round 40px)`,opacity:1}, {clipPath:'inset(0 0px 0 0 round 40px)',opacity:1}],440,456);
    animate(document.querySelector('.brand-mark'),[{transform:'scale(.015)',offset:0},{transform:'scale(1.3)',offset:.65},{transform:'scale(1)',offset:1}],800,0,'ease-in-out');
    for (const selector of ['.search-field','.search-submit']) animate(document.querySelector(selector),[{opacity:0},{opacity:1}],160,800);
    document.querySelectorAll('.matrix-nav .section-tab').forEach((el,i)=>animate(el,[{opacity:0,transform:'perspective(650px) rotateX(-86deg)'},{opacity:1,transform:'perspective(650px) rotateX(0deg)'}],420,i*90));
    document.querySelectorAll('.accordion-panel').forEach((el,i)=>animate(el,[{opacity:0,transform:'perspective(650px) rotateX(-86deg)'},{opacity:1,transform:'perspective(650px) rotateX(0deg)'}],420,380+i*90));
    reduced.addEventListener('change',finish,{once:true});
    await Promise.all(animations.map(a=>a.finished.catch(()=>{})));
    reduced.removeEventListener('change',finish);
  } finally { finish(); }
}
initBlogEntrance();


function syncArticleContents() {
  let id;
  const sleeve = document.querySelector('.article-heading');
  const threshold = matchMedia('(max-width: 680px)').matches ? 171 : Math.max(300, (sleeve?.getBoundingClientRect().bottom || 0) + 16) + 2;
  document.querySelectorAll('.article-body h2[id]').forEach(h => {
    if (h.getBoundingClientRect().top <= threshold) id = h.id;
  });
  document.querySelectorAll('.article-contents a').forEach(a => {
    if (id && a.hash === '#' + id) a.setAttribute('aria-current','location');
    else a.removeAttribute('aria-current');
  });
}
addEventListener('scroll',syncArticleContents,{passive:true});
addEventListener('resize',syncArticleContents);
addEventListener('hashchange',()=>requestAnimationFrame(syncArticleContents));
requestAnimationFrame(syncArticleContents);
document.fonts.ready.then(syncArticleContents);

function articleAnchorClearance(base,headerBottom,headingPosition,headingTop,headingHeight){
 const sticky=headingPosition==='sticky'||headingPosition==='fixed';
 return Math.max(base,headerBottom+8,sticky?headingTop+headingHeight+16:0);
}
function initArticleAnchorClearance(){
 const headings=[...document.querySelectorAll('.article-body h2[id]')];
 if(!headings.length)return;
 const sleeve=document.querySelector('.article-heading'),header=document.querySelector('.header-sticky');
 function update(){
  const headerStyle=header?getComputedStyle(header):null;
  const headerBottom=header?(parseFloat(headerStyle.top)||0)+header.getBoundingClientRect().height:0;
  const style=sleeve?getComputedStyle(sleeve):null;
  headings.forEach(heading=>{
   heading.style.removeProperty('scroll-margin-top');
   const base=parseFloat(getComputedStyle(heading).scrollMarginTop)||0;
   const offset=articleAnchorClearance(base,headerBottom,style?.position||'static',parseFloat(style?.top)||0,sleeve?.getBoundingClientRect().height||0);
   heading.style.scrollMarginTop=offset+'px';
  });
 }
 update();
 document.addEventListener('click',event=>{if(event.target.closest('.article-contents a[href^="#"]'))update();},true);
 addEventListener('resize',update);
 if(sleeve)new ResizeObserver(update).observe(sleeve);
 if(header)new ResizeObserver(update).observe(header);
 const initialHash=location.hash;
 document.fonts.ready.then(()=>{
  update();
  if(initialHash&&location.hash===initialHash){
   let target;try{target=document.getElementById(decodeURIComponent(initialHash.slice(1)));}catch(_error){}
   if(target?.matches('.article-body h2[id]'))requestAnimationFrame(()=>target.scrollIntoView({block:'start',behavior:'instant'}));
  }
 });
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initArticleAnchorClearance,{once:true});
else initArticleAnchorClearance();
